import java.util.*;import com.koios.game.arpg.*;import com.koios.game.model.*;import com.koios.game.model.player.Player;import com.koios.game.model.item.*;import com.koios.game.model.mob.*;import com.koios.game.map.*;
public final class HubServicesCheck {
 static int checks;static void check(boolean b,String label){checks++;if(!b)throw new AssertionError(label);}
 static Player fixture(String name,int index){Player p=PrototypeIntegrationCheck.player(name,index);p.setAttribute("starter-claimed",true);p.setAttribute("tutorial-stage",11);p.setAttribute("intro-complete",true);MapRuns.home(p);PrototypeIntegrationCheck.idle(p);p.getInventory().set(0,new Item(995,500));return p;}
 static HubServices.ServiceMob quarter(Player p){return HubServices.services(p).get(0);}
 static void approach(Player p,HubServices.ServiceMob mob){for(Location at:MapRuns.reachable(mob.getLocation(),2))if(!at.equals(mob.getLocation())&&MapRegion.getObject(at.getX(),at.getY(),0)==null){p.setPosition(at.copy());PrototypeIntegrationCheck.idle(p);return;}throw new AssertionError("No approach");}
 static void reject(Player p,String offer,String label){int coins=p.getInventory().getCount(995),size=p.getInventory().size();try{HubServices.buy(p,offer);throw new AssertionError(label+" accepted");}catch(IllegalArgumentException expected){}check(coins==p.getInventory().getCount(995)&&size==p.getInventory().size(),label+" leaves inventory/coins unchanged");}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();Player p=fixture("hubcheck",66),other=fixture("otherhub",67);java.util.List<HubServices.ServiceMob> original=new ArrayList<>(HubServices.services(p));check(original.size()==2,"Exactly two private services");for(HubServices.ServiceMob mob:original){check(mob.owner==p&&!mob.isAttackable(),"Owned service cannot be attacked");check(MobManager.mobs[mob.getIndex()]==mob&&mob.getSize()==1,"Registered service has verified template footprint");check(MapRegion.getClipping(mob.getX(),mob.getY(),0)==0&&MapRegion.getObject(mob.getX(),mob.getY(),0)==null,"Service stands on free floor");}MapRuns.home(p);PrototypeIntegrationCheck.idle(p);check(HubServices.services(p).equals(original),"Home revisit retains services without duplicates");
  HubServices.ServiceMob q=quarter(p);approach(p,q);p.mobClickIndex=q.getIndex();com.koios.game.model.player.EntityInteraction.firstClickMob(p,q.getId());HubServices.buy(p,"portals");check(p.getInventory().getCount(MapRuns.PORTAL_SCROLL)==5&&p.getInventory().getCount(995)==475,"Five scroll offer has exact price and quantity");reject(p,"portals","Replayed successful purchase");
  HubServices.handle(p,"hub supplies");HubServices.buy(p,"map");check(p.getInventory().getCount(995)==450,"Training map priced25");boolean map=false;for(int s=0;s<28;s++){Item i=p.getInventory().get(s);if(MapRuns.isMap(i))map=i.getRoll().getMap().tier==1&&i.getRoll().getMap().mods==0;}check(map,"Quartermaster sells only unmodified T1 map");HubServices.handle(p,"hub supplies");HubServices.buy(p,"wisdom");check(p.getInventory().getCount(CraftingCurrency.IDS[5])==1&&p.getInventory().getCount(995)==430,"Wisdom20coins");
  HubServices.handle(p,"hub supplies");p.setPosition(q.getX()+10,q.getY(),0);PrototypeIntegrationCheck.idle(p);reject(p,"map","Remote purchase");approach(p,q);HubServices.handle(p,"hub supplies");p.getInventory().set(0,new Item(995,1));reject(p,"map","Insufficient funds");p.getInventory().set(0,new Item(995,500));for(int slot=1;slot<28;slot++)p.getInventory().set(slot,new Item(385));reject(p,"map","Full inventory");p.getInventory().set(27,null);reject(p,"unknown","Unknown supply");
  for(int state=0;state<4;state++){HubServices.handle(p,"hub supplies");if(state==0)p.setDead(true);if(state==1)p.setIsTrading(true);if(state==2)p.getBankField().setBanking(true);if(state==3)p.setTeleporting(true);reject(p,"map","Busy state "+state);p.setDead(false);p.setIsTrading(false);p.getBankField().setBanking(false);PrototypeIntegrationCheck.idle(p);}
  HubServices.handle(p,"hub supplies");p.setPosition(p.getX(),p.getY(),1);PrototypeIntegrationCheck.idle(p);reject(p,"map","Wrong height");p.setPosition(p.getX(),p.getY(),0);PrototypeIntegrationCheck.idle(p);
  p.setAttribute("tutorial-stage",4);HubServices.interact(p,q);reject(p,"map","Tutorial cannot bypass service gate");p.setAttribute("tutorial-stage",11);
  other.setPosition(q.getLocation().copy());PrototypeIntegrationCheck.idle(other);HubServices.interact(other,q);reject(other,"map","Cross-owner interaction");check(HubServices.services(other).get(0)!=q,"Other home owns different NPCs");
  approach(p,original.get(1));HubServices.interact(p,original.get(1));reject(p,"map","Gemcutter cannot sell supplies");p.getInventory().set(27,MapRuns.map(1,0,1));MapRuns.start(p,27,false);PrototypeIntegrationCheck.idle(p);for(HubServices.ServiceMob mob:original){mob.update();check(MobManager.mobs[mob.getIndex()]==mob,"Services survive while owner explores a map");}MapRuns.home(p);PrototypeIntegrationCheck.idle(p);check(HubServices.services(p).equals(original),"Returning from map retains service identities");for(HubServices.ServiceMob mob:original)check(!mob.getLocation().equals(MapRuns.run(p).basePortal),"Map return portal never overlaps service anchor");MapRuns.cleanup(p);for(HubServices.ServiceMob mob:original)check(MobManager.mobs[mob.getIndex()]!=mob,"Cleanup unregisters physical NPC");check(HubServices.services(p).isEmpty(),"Cleanup releases service ownership");MapRuns.home(p);PrototypeIntegrationCheck.idle(p);check(HubServices.services(p).size()==2&&!HubServices.services(p).contains(q),"Reconnect rebuilds fresh service instances");HubServices.interact(p,q);reject(p,"map","Stale service reference");MapRuns.cleanup(p);MapRuns.cleanup(other);System.out.println("Passed "+checks+" private hub service checks.");}
}
